text:
Laboratorio: tu cartera de problemas


Laboratorio · se ejecuta en tu navegador; tus datos no salen de él

Escribe hasta cinco ideas de proyecto, una por línea, con el formato idea; dificultad (1-5); ganancia (1-5). El laboratorio las sitúa en la matriz de Alon y valora el equilibrio de tu cartera.

area = window.Lab.area
viewof ideas = area("Ideas de proyecto", {rows: 5, submit: "Situar", value: "Revisión sistemática del tema de la tesis; 2; 3\nReanálisis de los datos del grupo con nuevos métodos; 2; 4\nEncuesta internacional propia; 4; 4\nNuevo método de medición; 5; 5\nCapítulo descriptivo de la base de datos; 1; 1"})
















{
  const filas = ideas.split("\n").map(l =&gt; l.split(";").map(s =&gt; s.trim())).filter(f =&gt; f.length &gt;= 3 && f[0]).slice(0, 5)
    .map(([t, d, g]) =&gt; ({t, d: Math.min(5, Math.max(1, +d || 3)), g: Math.min(5, Math.max(1, +g || 3))}));
  const cuad = f =&gt; f.d &lt;= 3 && f.g &gt;= 3 ? "Lo mejor: viable y valioso" : f.d &lt;= 3 ? "Buen comienzo para aprender" : f.g &gt;= 3 ? "Apuesta a largo plazo" : "Mejor evitarlo";
  const X = d =&gt; 60 + (d - 1) * 105, Y = g =&gt; 280 - (g - 1) * 60;
  const pts = filas.map((f, i) =&gt; `&lt;circle cx="${X(f.d)}" cy="${Y(f.g)}" r="13" fill="#2a78d6" stroke="var(--bs-body-bg)" stroke-width="2"/&gt;&lt;text x="${X(f.d)}" y="${Y(f.g) + 4.5}" text-anchor="middle" font-size="13" font-weight="700" fill="#fff"&gt;${i + 1}&lt;/text&gt;`).join("");
  const seguros = filas.filter(f =&gt; f.d &lt;= 2).length, apuestas = filas.filter(f =&gt; f.d &gt;= 4 && f.g &gt;= 4).length, malos = filas.filter(f =&gt; f.d &gt;= 3 && f.g &lt;= 2).length;
  const consejo = !filas.length ? "Escribe al menos una idea." : seguros === 0 ? "Tu cartera no tiene proyectos seguros: añade uno viable a corto plazo para no depender solo de apuestas." :
    apuestas === 0 ? "No hay ninguna apuesta ambiciosa: valora incluir un proyecto difícil de gran interés, a largo plazo." :
    apuestas &gt; 2 ? "Demasiadas apuestas a la vez: el riesgo de quedarte sin resultados es alto." : "Cartera equilibrada: combina proyectos seguros y alguna apuesta.";
  const d = html`&lt;div role="status"&gt;&lt;/div&gt;`;
  d.innerHTML = `&lt;svg viewBox="0 0 540 320" width="100%" style="max-width:540px" role="img" aria-label="Matriz de dificultad y ganancia con las ideas numeradas"&gt;
    &lt;rect x="40" y="10" width="240" height="140" fill="#1baf7a" opacity=".16"/&gt;&lt;rect x="280" y="10" width="240" height="140" fill="#eda100" opacity=".16"/&gt;
    &lt;rect x="40" y="150" width="240" height="140" fill="#2a78d6" opacity=".12"/&gt;&lt;rect x="280" y="150" width="240" height="140" fill="#a3a29e" opacity=".18"/&gt;
    &lt;text x="50" y="28" font-size="12" fill="currentColor"&gt;Lo mejor&lt;/text&gt;&lt;text x="510" y="28" text-anchor="end" font-size="12" fill="currentColor"&gt;Apuesta a largo plazo&lt;/text&gt;
    &lt;text x="50" y="282" font-size="12" fill="currentColor"&gt;Para aprender&lt;/text&gt;&lt;text x="510" y="282" text-anchor="end" font-size="12" fill="currentColor"&gt;Evitar&lt;/text&gt;
    &lt;text x="280" y="312" text-anchor="middle" font-size="12" fill="currentColor"&gt;Dificultad →&lt;/text&gt;&lt;text x="20" y="150" text-anchor="middle" font-size="12" fill="currentColor" transform="rotate(-90 20 150)"&gt;Ganancia →&lt;/text&gt;${pts}&lt;/svg&gt;
    &lt;ol&gt;${filas.map(f =&gt; `&lt;li&gt;${f.t.replace(/&lt;/g, "&lt;")}: &lt;strong&gt;${cuad(f)}&lt;/strong&gt;&lt;/li&gt;`).join("")}&lt;/ol&gt;
    &lt;p style="font-weight:600" class="${seguros && apuestas && apuestas &lt;= 2 ? "lab-bien" : "lab-medio"}"&gt;${consejo}&lt;/p&gt;${malos ? `&lt;p class="small"&gt;${malos} idea${malos &gt; 1 ? "s" : ""} con mucho esfuerzo y poca ganancia: ¿puedes reformularla${malos &gt; 1 ? "s" : ""} o descartarla${malos &gt; 1 ? "s" : ""}?&lt;/p&gt;` : ""}`;
  return d;
}

Laboratorio: ¿a qué dedicas tu semana?


Laboratorio · se ejecuta en tu navegador

Indica las horas semanales que dedicas, de verdad, a cada actividad y cuál es tu prioridad principal este año.

rango = window.Lab.rango
seleccion = window.Lab.seleccion
viewof h_inv = rango("Investigar (datos, experimentos, análisis)", [0, 40], {value: 12})
viewof h_esc = rango("Escribir (artículos, tesis, solicitudes)", [0, 40], {value: 4})
viewof h_doc = rango("Docencia y tutorías", [0, 40], {value: 8})
viewof h_ges = rango("Gestión, correo y reuniones", [0, 40], {value: 12})
viewof h_for = rango("Formación y lectura", [0, 40], {value: 3})
viewof h_red = rango("Red profesional y divulgación", [0, 40], {value: 1})
viewof prioridad = seleccion("Prioridad principal este año", ["Investigar", "Escribir", "Docencia", "Formación", "Red profesional"], {value: "Escribir"})

































































{
  const act = [["Investigar", h_inv, "#2a78d6"], ["Escribir", h_esc, "#eb6834"], ["Docencia", h_doc, "#1baf7a"], ["Gestión", h_ges, "#a3a29e"], ["Formación", h_for, "#eda100"], ["Red profesional", h_red, "#e87ba4"]];
  const tot = act.reduce((s, a) =&gt; s + a[1], 0) || 1;
  let x = 0; const barras = act.map(([n, h, c]) =&gt; { const w = 520 * h / tot, r = `&lt;rect x="${x}" y="0" width="${Math.max(0, w - 2)}" height="34" fill="${c}"&gt;&lt;title&gt;${n}: ${h} h&lt;/title&gt;&lt;/rect&gt;`; x += w; return r; }).join("");
  const hp = act.find(a =&gt; a[0] === prioridad)[1], pp = 100 * hp / tot, pg = 100 * h_ges / tot;
  const pc = v =&gt; v.toFixed(0) + " %";
  const msg = pp &lt; 20 ? `Tu prioridad (${prioridad.toLowerCase()}) solo recibe el ${pc(pp)} de tu tiempo. Reserva bloques fijos para ella.` : `Tu prioridad recibe el ${pc(pp)} del tiempo: coherente con lo que dices que importa.`;
  const d = html`&lt;div role="status"&gt;&lt;/div&gt;`;
  d.innerHTML = `&lt;p&gt;&lt;strong&gt;${tot} horas&lt;/strong&gt; a la semana${tot &gt; 50 ? ' &lt;span class="lab-mal" style="font-weight:600"&gt;· una carga difícil de sostener&lt;/span&gt;' : ""}.&lt;/p&gt;
   &lt;svg viewBox="0 0 520 34" width="100%" style="max-width:520px" role="img" aria-label="Reparto del tiempo semanal"&gt;${barras}&lt;/svg&gt;
   &lt;ul class="small"&gt;${act.map(([n, h]) =&gt; `&lt;li&gt;${n}: ${h} h (${pc(100 * h / tot)})&lt;/li&gt;`).join("")}&lt;/ul&gt;
   &lt;p style="font-weight:600" class="${pp &lt; 20 ? "lab-medio" : "lab-bien"}"&gt;${msg}&lt;/p&gt;
   ${pg &gt; 30 ? `&lt;p class="small"&gt;La gestión, el correo y las reuniones ocupan el ${pc(pg)}: agrúpalos en franjas y revisa qué reuniones son imprescindibles.&lt;/p&gt;` : ""}`;
  return d;
}

Laboratorio: tu perfil de conductas de liderazgo


Laboratorio · se ejecuta en tu navegador

Valora de 1 (casi nunca) a 5 (casi siempre) con qué frecuencia haces cada conducta. Lo ideal es pedir a dos o tres personas que te valoren también y comparar.

rango = window.Lab.rango
viewof l1 = rango("Comparto una visión clara de hacia dónde vamos", [1, 5], {value: 3})
viewof l2 = rango("Animo a cuestionar ideas, incluidas las mías", [1, 5], {value: 4})
viewof l3 = rango("Presto atención a las necesidades de cada persona", [1, 5], {value: 3})
viewof l4 = rango("Acuerdo expectativas y plazos de forma explícita", [1, 5], {value: 2})
viewof l5 = rango("Reconozco el trabajo bien hecho", [1, 5], {value: 3})
viewof l6 = rango("Abordo los problemas y conflictos a tiempo", [1, 5], {value: 2})



















































{
  const ej = [["Visión", l1], ["Estímulo intelectual", l2], ["Atención individual", l3], ["Expectativas claras", l4], ["Reconocimiento", l5], ["Afrontar problemas", l6]];
  const cx = 170, cy = 150, R = 110, ang = i =&gt; -Math.PI / 2 + i * 2 * Math.PI / 6, P = (i, v) =&gt; [cx + R * v / 5 * Math.cos(ang(i)), cy + R * v / 5 * Math.sin(ang(i))];
  const red = [1, 2, 3, 4, 5].map(v =&gt; `&lt;polygon points="${ej.map((_, i) =&gt; P(i, v).join(",")).join(" ")}" fill="none" stroke="currentColor" opacity=".2"/&gt;`).join("");
  const eti = ej.map(([n], i) =&gt; { const [x, y] = P(i, 6.1); return `&lt;text x="${x}" y="${y}" text-anchor="middle" font-size="11.5" fill="currentColor"&gt;${n}&lt;/text&gt;`; }).join("");
  const pol = `&lt;polygon points="${ej.map(([, v], i) =&gt; P(i, v).join(",")).join(" ")}" fill="#2a78d6" fill-opacity=".3" stroke="#2a78d6" stroke-width="2"/&gt;`;
  const orden = [...ej].sort((a, b) =&gt; a[1] - b[1]);
  const d = html`&lt;div role="status"&gt;&lt;/div&gt;`;
  d.innerHTML = `&lt;svg viewBox="-10 0 360 300" width="100%" style="max-width:420px" role="img" aria-label="Gráfico radial de las seis conductas"&gt;${red}${eti}${pol}&lt;/svg&gt;
   &lt;p&gt;Punto fuerte: &lt;strong&gt;${orden[5][0].toLowerCase()}&lt;/strong&gt; (${orden[5][1]}). Área de mejora: &lt;strong&gt;${orden[0][0].toLowerCase()}&lt;/strong&gt; (${orden[0][1]}).&lt;/p&gt;
   &lt;p class="small"&gt;Las cuatro primeras conductas son propias del liderazgo transformacional; expectativas y reconocimiento, del transaccional constructivo; afrontar los problemas es lo contrario del &lt;em&gt;laissez-faire&lt;/em&gt;. Elige una sola conducta para practicar este mes.&lt;/p&gt;`;
  return d;
}

Laboratorio: declaración de contribuciones CRediT


Laboratorio · se ejecuta en tu navegador

Escribe una línea por persona con el formato Nombre: números de roles. Los roles son: 1 Conceptualización · 2 Curación de datos · 3 Análisis formal · 4 Obtención de financiación · 5 Investigación · 6 Metodología · 7 Administración del proyecto · 8 Recursos · 9 Software · 10 Supervisión · 11 Validación · 12 Visualización · 13 Redacción (borrador original) · 14 Redacción (revisión y edición).

area = window.Lab.area
viewof contrib = area("Contribuciones", {rows: 4, submit: "Generar declaración", value: "Ana Ruiz: 1, 2, 3, 5, 9, 12, 13\nLuis Martín: 1, 6, 10, 14\nMarta Gil: 4\nPedro Sanz: 5, 11, 14"})
















{
  const es = ["Conceptualización", "Curación de datos", "Análisis formal", "Obtención de financiación", "Investigación", "Metodología", "Administración del proyecto", "Recursos", "Software", "Supervisión", "Validación", "Visualización", "Redacción (borrador original)", "Redacción (revisión y edición)"];
  const en = ["Conceptualization", "Data curation", "Formal analysis", "Funding acquisition", "Investigation", "Methodology", "Project administration", "Resources", "Software", "Supervision", "Validation", "Visualization", "Writing – original draft", "Writing – review & editing"];
  const esc = s =&gt; s.replace(/&/g, "&amp;").replace(/&lt;/g, "&lt;");
  const gente = contrib.split("\n").map(l =&gt; l.split(":")).filter(p =&gt; p.length &gt; 1 && p[0].trim())
    .map(([n, r]) =&gt; [n.trim(), [...new Set((r.match(/\d+/g) || []).map(Number).filter(x =&gt; x &gt;= 1 && x &lt;= 14))].sort((a, b) =&gt; a - b)]);
  const decl = (L) =&gt; gente.map(([n, r]) =&gt; `&lt;strong&gt;${esc(n)}&lt;/strong&gt;: ${r.map(i =&gt; L[i - 1]).join(", ") || "—"}.`).join(" ");
  const usados = new Set(gente.flatMap(g =&gt; g[1]));
  const sinNadie = [1, 3, 5, 13, 14].filter(i =&gt; !usados.has(i)).map(i =&gt; es[i - 1].toLowerCase());
  const soloAdmin = gente.filter(([, r]) =&gt; r.length && r.every(i =&gt; [4, 7, 8, 10].includes(i))).map(g =&gt; g[0]);
  const sinRedaccion = gente.filter(([, r]) =&gt; !r.includes(13) && !r.includes(14)).map(g =&gt; g[0]);
  const d = html`&lt;div role="status"&gt;&lt;/div&gt;`;
  d.innerHTML = `&lt;p&gt;&lt;strong&gt;Declaración (español)&lt;/strong&gt;&lt;/p&gt;&lt;p&gt;${decl(es)}&lt;/p&gt;&lt;p&gt;&lt;strong&gt;CRediT statement (English)&lt;/strong&gt;&lt;/p&gt;&lt;p lang="en"&gt;${decl(en)}&lt;/p&gt;
   ${sinNadie.length ? `&lt;p class="lab-medio" style="font-weight:600"&gt;Nadie figura en: ${sinNadie.join(", ")}. ¿Falta alguien o algún rol?&lt;/p&gt;` : ""}
   ${soloAdmin.length ? `&lt;p class="lab-mal" style="font-weight:600"&gt;${soloAdmin.map(esc).join(", ")}: solo roles de financiación, recursos, administración o supervisión. Según el ICMJE, eso por sí solo no justifica la autoría; valora los agradecimientos.&lt;/p&gt;` : ""}
   ${sinRedaccion.length ? `&lt;p class="small"&gt;${sinRedaccion.map(esc).join(", ")} no participa en la redacción ni en la revisión: los criterios del ICMJE piden revisar críticamente y aprobar la versión final.&lt;/p&gt;` : ""}`;
  return d;
}

Laboratorio: matriz de riesgos


Laboratorio · se ejecuta en tu navegador

Escribe un riesgo por línea con el formato riesgo; probabilidad (1-5); impacto (1-5).

area = window.Lab.area
viewof riesgos = area("Riesgos del proyecto", {rows: 5, submit: "Valorar", value: "Retraso en el acceso a los datos administrativos; 4; 5\nBaja tasa de respuesta de los programas; 3; 3\nMarcha de la persona contratada; 2; 4\nFallo del servidor de análisis; 1; 2\nCambio de normativa de protección de datos; 2; 5"})
















{
  const fs = riesgos.split("\n").map(l =&gt; l.split(";").map(s =&gt; s.trim())).filter(f =&gt; f.length &gt;= 3 && f[0])
    .map(([t, p, i]) =&gt; ({t, p: Math.min(5, Math.max(1, +p || 1)), i: Math.min(5, Math.max(1, +i || 1))})).map(r =&gt; ({...r, v: r.p * r.i})).sort((a, b) =&gt; b.v - a.v);
  const nivel = v =&gt; v &gt;= 15 ? ["Alto", "lab-mal", "Mitigación y contingencia obligatorias; vigílalo cada mes."] : v &gt;= 8 ? ["Medio", "lab-medio", "Plan de mitigación y responsable."] : ["Bajo", "lab-bien", "Basta con vigilarlo."];
  const col = (p, i) =&gt; p * i &gt;= 15 ? "#e0533d" : p * i &gt;= 8 ? "#eda100" : "#1baf7a";
  let celdas = "";
  for (let p = 1; p &lt;= 5; p++) for (let i = 1; i &lt;= 5; i++) celdas += `&lt;rect x="${40 + (i - 1) * 50}" y="${10 + (5 - p) * 40}" width="48" height="38" fill="${col(p, i)}" opacity=".28"/&gt;`;
  const marcas = fs.map((r, k) =&gt; { const mismos = fs.slice(0, k).filter(o =&gt; o.p === r.p && o.i === r.i).length;
    return `&lt;circle cx="${40 + (r.i - 1) * 50 + 24 + mismos * 10 - 5}" cy="${10 + (5 - r.p) * 40 + 19}" r="10" fill="#0b0b0b" stroke="#fff" stroke-width="1.5"/&gt;&lt;text x="${40 + (r.i - 1) * 50 + 24 + mismos * 10 - 5}" y="${10 + (5 - r.p) * 40 + 23.5}" text-anchor="middle" font-size="12" font-weight="700" fill="#fff"&gt;${k + 1}&lt;/text&gt;`; }).join("");
  const d = html`&lt;div role="status"&gt;&lt;/div&gt;`;
  d.innerHTML = `&lt;svg viewBox="0 0 300 240" width="100%" style="max-width:360px" role="img" aria-label="Matriz de probabilidad por impacto con los riesgos numerados"&gt;${celdas}${marcas}
    &lt;text x="165" y="232" text-anchor="middle" font-size="12" fill="currentColor"&gt;Impacto →&lt;/text&gt;&lt;text x="18" y="110" text-anchor="middle" font-size="12" fill="currentColor" transform="rotate(-90 18 110)"&gt;Probabilidad →&lt;/text&gt;&lt;/svg&gt;
    &lt;ol&gt;${fs.map(r =&gt; { const [n, c, a] = nivel(r.v); return `&lt;li&gt;${r.t.replace(/&lt;/g, "&lt;")} · ${r.p} × ${r.i} = ${r.v} · &lt;span class="${c}" style="font-weight:600"&gt;${n}&lt;/span&gt;. ${a}&lt;/li&gt;`; }).join("")}&lt;/ol&gt;`;
  return d;
}

Laboratorio: matriz de decisión ponderada


Laboratorio · se ejecuta en tu navegador

Ejemplo: elegir entre tres ofertas posdoctorales. Ajusta la importancia de cada criterio (0-5) y la puntuación de cada opción (1-5). Prueba a cambiar los pesos: ¿cambia la decisión?

rango = window.Lab.rango
viewof w1 = rango("Peso · encaje científico", [0, 5], {value: 5})
viewof w2 = rango("Peso · estabilidad del contrato", [0, 5], {value: 3})
viewof w3 = rango("Peso · calidad de la mentoría", [0, 5], {value: 4})
viewof w4 = rango("Peso · vida personal y ubicación", [0, 5], {value: 3})





































viewof notas = {
  const crit = ["Encaje científico", "Estabilidad", "Mentoría", "Vida personal"], ops = ["Grupo A (extranjero)", "Grupo B (misma ciudad)", "Empresa C"];
  const ini = [[5, 2, 4, 2], [3, 3, 3, 5], [2, 5, 2, 4]];
  const t = html`&lt;table class="table table-sm"&gt;&lt;caption&gt;Puntuaciones de 1 a 5&lt;/caption&gt;&lt;thead&gt;&lt;tr&gt;&lt;th scope="col"&gt;Opción&lt;/th&gt;${crit.map(c =&gt; `&lt;th scope="col"&gt;${c}&lt;/th&gt;`).join("")}&lt;/tr&gt;&lt;/thead&gt;&lt;tbody&gt;${ops.map((o, i) =&gt; `&lt;tr&gt;&lt;th scope="row"&gt;${o}&lt;/th&gt;${crit.map((c, j) =&gt; `&lt;td&gt;&lt;input type="number" min="1" max="5" value="${ini[i][j]}" aria-label="${o}, ${c}" style="width:3.5em" class="form-control form-control-sm"&gt;&lt;/td&gt;`).join("")}&lt;/tr&gt;`).join("")}&lt;/tbody&gt;&lt;/table&gt;`;
  const leer = () =&gt; ops.map((o, i) =&gt; [o, [...t.querySelectorAll("tbody tr")[i].querySelectorAll("input")].map(x =&gt; Math.min(5, Math.max(1, +x.value || 1)))]);
  t.value = leer(); t.addEventListener("input", () =&gt; { t.value = leer(); });
  return t;
}







{
  const W = [w1, w2, w3, w4], sw = W.reduce((a, b) =&gt; a + b, 0) || 1;
  const res = notas.map(([o, v]) =&gt; [o, v.reduce((s, x, j) =&gt; s + x * W[j], 0) / sw]).sort((a, b) =&gt; b[1] - a[1]);
  const dif = res[0][1] - res[1][1];
  const d = html`&lt;div role="status"&gt;&lt;/div&gt;`;
  d.innerHTML = `&lt;ol&gt;${res.map(([o, s]) =&gt; `&lt;li&gt;${o}: &lt;strong&gt;${s.toFixed(2).replace(".", ",")}&lt;/strong&gt; sobre 5&lt;/li&gt;`).join("")}&lt;/ol&gt;
   &lt;p style="font-weight:600" class="${dif &lt; 0.3 ? "lab-medio" : "lab-bien"}"&gt;${dif &lt; 0.3 ? "Diferencia muy pequeña: la decisión depende de matices que la matriz no recoge. Habla con personas de cada grupo." : `Gana ${res[0][0]} con un margen claro (${dif.toFixed(2).replace(".", ",")} puntos).`}&lt;/p&gt;
   &lt;p class="small"&gt;La matriz no decide por ti: si el resultado te decepciona, quizá hay un criterio que no has escrito. Eso también es información.&lt;/p&gt;`;
  return d;
}
